class ApprovedMarketActivity : ComponentActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContent { ApprovedApp() }
    }
}

private enum class Screen { HOME, MARKET, COMPANIES, PAPER, MORE, COMPANY, PROFILE, SETTINGS }

@Composable
private fun ApprovedApp() {
    val context = LocalContext.current
    val prefs = remember { context.getSharedPreferences("nse_watcher_preferences", Context.MODE_PRIVATE) }
    var screen by rememberSaveable { mutableStateOf(Screen.HOME) }
    var selectedTab by rememberSaveable { mutableIntStateOf(0) }
    var selectedStock by remember { mutableStateOf<Stock?>(null) }
    var stocks by remember { mutableStateOf(emptyList<Stock>()) }
    var dark by rememberSaveable { mutableStateOf(prefs.getBoolean("dark_mode", false)) }

    LaunchedEffect(Unit) { MyStocksCache.loadStocks().takeIf { it.isNotEmpty() }?.let { stocks = it } }

    val scheme = if (dark) darkColorScheme(primary = Color(0xFF32D486), background = Color(0xFF0D1712), surface = Color(0xFF132019), onSurface = Color.White, onBackground = Color.White) else lightColorScheme(primary = AGreen, background = Color.White, surface = Color.White, onSurface = AText, onBackground = AText, onSurfaceVariant = AMuted)

    BackHandler(enabled = screen != Screen.HOME) { screen = when (screen) { Screen.MARKET, Screen.COMPANIES, Screen.PAPER, Screen.MORE -> Screen.HOME; Screen.COMPANY -> Screen.COMPANIES; Screen.PROFILE, Screen.SETTINGS -> Screen.HOME; Screen.HOME -> Screen.HOME } }

    MaterialTheme(colorScheme = scheme) {
        Surface(modifier = Modifier.fillMaxSize(), color = scheme.background) {
            when (screen) {
                Screen.HOME, Screen.MARKET, Screen.COMPANIES, Screen.PAPER, Screen.MORE -> Scaffold(topBar = { ApprovedTopBar { screen = Screen.PROFILE } }, bottomBar = { ApprovedBottomNav(selectedTab) { index -> selectedTab = index; screen = when (index) { 0 -> Screen.HOME; 1 -> Screen.MARKET; 2 -> Screen.COMPANIES; 3 -> Screen.PAPER; else -> Screen.MORE } } }) { padding -> Box(Modifier.fillMaxSize().padding(padding)) { when (screen) { Screen.HOME -> ApprovedHome(stocks); Screen.MARKET -> ApprovedMarket(stocks); Screen.COMPANIES -> ApprovedCompanies(stocks) { selectedStock = it; screen = Screen.COMPANY }; Screen.PAPER -> ApprovedSimplePage("Paper Invest", Icons.Default.AccountBalanceWallet, "Practice with virtual money using market prices."); Screen.MORE -> ApprovedSimplePage("More", Icons.Default.AutoGraph, "Alerts, help, information and other NSE Watcher tools."); else -> Unit } } }
                Screen.COMPANY -> ApprovedCompany(selectedStock ?: stocks.firstOrNull()) { screen = Screen.COMPANIES }
                Screen.PROFILE -> ApprovedProfile({ screen = Screen.HOME }) { screen = Screen.SETTINGS }
                Screen.SETTINGS -> ApprovedSettings(dark, { dark = it; prefs.edit().putBoolean("dark_mode", it).apply() }) { screen = Screen.PROFILE }
            }
        }
    }
}

@Composable private fun ApprovedTopBar(onProfile: () -> Unit) { Row(Modifier.fillMaxWidth().padding(horizontal = 20.dp, vertical = 10.dp), verticalAlignment = Alignment.CenterVertically) { Surface(modifier = Modifier.size(42.dp), shape = RoundedCornerShape(12.dp), color = ALightGreen) { Icon(Icons.Default.ShowChart, null, Modifier.padding(8.dp), AGreen) }; Spacer(Modifier.width(10.dp)); Column(Modifier.weight(1f)) { Text("NSE Watcher", fontSize = 18.sp, fontWeight = FontWeight.ExtraBold); Text("Analyse • Understand • Invest Smarter", fontSize = 10.sp, color = AMuted) }; IconButton(onClick = {}) { Icon(Icons.Default.Search, "Search", tint = AGreen) }; Surface(modifier = Modifier.size(40.dp).clip(CircleShape).clickable(onClick = onProfile), shape = CircleShape, color = ALightGreen) { Box(Modifier.fillMaxSize(), Alignment.Center) { Text("J", color = AGreen, fontWeight = FontWeight.Bold) } } } }

@Composable private fun ApprovedBottomNav(selected: Int, onSelect: (Int) -> Unit) { val items = listOf("Home" to Icons.Default.Home, "Market" to Icons.Default.CandlestickChart, "Companies" to Icons.Default.Business, "Paper Invest" to Icons.Default.AccountBalanceWallet, "More" to Icons.Default.AutoGraph); NavigationBar(containerColor = Color(0xFFF9F2FC)) { items.forEachIndexed { index, item -> NavigationBarItem(selected = selected == index, onClick = { onSelect(index) }, icon = { Icon(item.second, item.first) }, label = { Text(item.first, fontSize = 9.sp) }, colors = NavigationBarItemDefaults.colors(selectedIconColor = AGreen, selectedTextColor = AGreen, indicatorColor = ALightGreen, unselectedIconColor = AMuted, unselectedTextColor = AMuted)) } } }

@Composable private fun ApprovedHome(stocks: List<Stock>) { val gainers = stocks.filter { it.change > 0 }.sortedByDescending { it.change }; val losers = stocks.filter { it.change < 0 }.sortedBy { it.change }; LazyColumn(contentPadding = PaddingValues(20.dp, 4.dp, 20.dp, 24.dp), verticalArrangement = Arrangement.spacedBy(12.dp)) { item { MarketStatusCard() }; item { IndexCards() }; item { MarketPulse(gainers, losers) }; item { NewsCard() }; item { PaperInvestBanner() } } }
