@Composable private fun IndexCards() { val values = listOf(Triple("NSE 20", "1,843.56", "+1.34%"), Triple("NASI", "112.48", "+1.34%"), Triple("NSE 25", "3,642.17", "+1.34%")); LazyRow(horizontalArrangement = Arrangement.spacedBy(10.dp)) { items(values) { (name, value, change) -> Card(Modifier.width(154.dp), RoundedCornerShape(16.dp), border = BorderStroke(1.dp, ABorder)) { Column(Modifier.padding(13.dp)) { Text(name, fontSize = 11.sp, fontWeight = FontWeight.Bold); Text(value, fontSize = 19.sp, fontWeight = FontWeight.ExtraBold); Text("▲ $change", color = AGreen, fontSize = 11.sp, fontWeight = FontWeight.Bold) } } } } }
@Composable private fun MarketPulse(gainers: List<Stock>, losers: List<Stock>) { val advancers = gainers.size; val decliners = losers.size; Card(Modifier.fillMaxWidth(), RoundedCornerShape(18.dp), border = BorderStroke(1.dp, ABorder)) { Column(Modifier.padding(16.dp)) { Row(verticalAlignment = Alignment.CenterVertically) { Icon(Icons.Default.MonitorHeart, null, tint = AGreen); Spacer(Modifier.width(8.dp)); Column { Text("Market Pulse", fontSize = 16.sp, fontWeight = FontWeight.ExtraBold); Text("Quick view of market activity and sentiment.", color = AMuted, fontSize = 11.sp) } }; Spacer(Modifier.height(14.dp)); Row(horizontalArrangement = Arrangement.spacedBy(10.dp)) { PulseBox(Modifier.weight(1f), "Advancers vs Decliners", "$advancers / $decliners", "${if (advancers + decliners == 0) 0 else (advancers * 100 / (advancers + decliners))}% Advancers", true); PulseBox(Modifier.weight(1f), "Strongest Sector", "Banking", "+2.48%", true) }; Spacer(Modifier.height(12.dp)); Row(horizontalArrangement = Arrangement.spacedBy(10.dp)) { MoverText("Top Gainer", gainers.firstOrNull()?.symbol ?: "—", gainers.firstOrNull()?.change ?: 0.0, true, Modifier.weight(1f)); MoverText("Top Loser", losers.firstOrNull()?.symbol ?: "—", losers.firstOrNull()?.change ?: 0.0, false, Modifier.weight(1f)) } } } }
@Composable private fun PulseBox(modifier: Modifier, title: String, value: String, sub: String, positive: Boolean) { Surface(modifier = modifier, shape = RoundedCornerShape(12.dp), color = Color(0xFFF8FBF9)) { Column(Modifier.padding(11.dp)) { Text(title, fontSize = 10.sp, fontWeight = FontWeight.Bold); Text(value, fontSize = 17.sp, fontWeight = FontWeight.ExtraBold); Text(sub, color = if (positive) AGreen else ARed, fontSize = 10.sp, fontWeight = FontWeight.Bold) } } }
@Composable private fun MoverText(title: String, symbol: String, change: Double, positive: Boolean, modifier: Modifier) { Column(modifier) { Text(title, fontSize = 10.sp, color = AMuted); Text(symbol, fontSize = 14.sp, fontWeight = FontWeight.Bold); Text(String.format("%+.2f%%", change), color = if (positive) AGreen else ARed, fontSize = 11.sp, fontWeight = FontWeight.Bold) } }
@Composable private fun NewsCard() { Card(Modifier.fillMaxWidth(), RoundedCornerShape(18.dp), border = BorderStroke(1.dp, ABorder)) { Column(Modifier.padding(16.dp)) { Row(verticalAlignment = Alignment.CenterVertically) { Icon(Icons.Default.Article, null, tint = AGreen); Spacer(Modifier.width(8.dp)); Column { Text("What's moving the market?", fontSize = 16.sp, fontWeight = FontWeight.ExtraBold); Text("News and events will feed this intelligence layer.", color = AMuted, fontSize = 11.sp) } }; Spacer(Modifier.height(12.dp)); Surface(shape = RoundedCornerShape(12.dp), color = ALightGreen) { Row(Modifier.fillMaxWidth().padding(12.dp), verticalAlignment = Alignment.CenterVertically) { Icon(Icons.Default.Insights, null, tint = AGreen); Spacer(Modifier.width(10.dp)); Column { Text("Market intelligence", fontWeight = FontWeight.Bold, fontSize = 12.sp); Text("Company news, announcements and market events will be combined here.", color = AMuted, fontSize = 10.sp) } } } } } }
