@Composable private fun ApprovedMarket(stocks: List<Stock>) { var period by rememberSaveable { mutableStateOf("1M") }; val gainers = stocks.filter { it.change > 0 }.sortedByDescending { it.change }; val losers = stocks.filter { it.change < 0 }.sortedBy { it.change }; val chart = remember(period) { marketTrend(period) }; LazyColumn(contentPadding = PaddingValues(20.dp, 4.dp, 20.dp, 24.dp), verticalArrangement = Arrangement.spacedBy(12.dp)) { item { MarketHeader() }; item { Card(Modifier.fillMaxWidth(), RoundedCornerShape(18.dp), border = BorderStroke(1.dp, ABorder)) { Column(Modifier.padding(15.dp)) { Row(verticalAlignment = Alignment.CenterVertically) { Column(Modifier.weight(1f)) { Text("NSE 20 — Market Trend", fontSize = 16.sp, fontWeight = FontWeight.ExtraBold); Text("See how the market has been performing.", color = AMuted, fontSize = 11.sp) }; Column(horizontalAlignment = Alignment.End) { Text("+1.34%", color = AGreen, fontSize = 19.sp, fontWeight = FontWeight.ExtraBold); Text("1,843.56", fontSize = 10.sp, fontWeight = FontWeight.Bold) } }; Spacer(Modifier.height(10.dp)); MarketLineChart(chart); Spacer(Modifier.height(8.dp)); PeriodSelector(period) { period = it }; Text("Historical data from NSE (15 min delayed) • ${chart.size} points", color = AMuted, fontSize = 9.sp, modifier = Modifier.padding(top = 7.dp)) } } }; item { BreadthCard(gainers.size, losers.size) }; item { SectorCard() }; item { MoversCard(gainers, losers) } } }
@Composable private fun MarketHeader() { Card(Modifier.fillMaxWidth(), RoundedCornerShape(18.dp), colors = CardDefaults.cardColors(containerColor = ALightGreen)) { Row(Modifier.padding(15.dp), verticalAlignment = Alignment.CenterVertically) { Box(Modifier.size(9.dp).clip(CircleShape).background(AGreen)); Spacer(Modifier.width(7.dp)); Column(Modifier.weight(1f)) { Text("NSE MARKET", color = ADarkGreen, fontWeight = FontWeight.ExtraBold, fontSize = 11.sp); Text("Market Analysis", fontSize = 20.sp, fontWeight = FontWeight.ExtraBold); Text("In-depth analysis and market trends.", color = AMuted, fontSize = 11.sp) }; Text("15 MIN DELAYED", color = AGreen, fontWeight = FontWeight.ExtraBold, fontSize = 10.sp) } } }
@Composable private fun PeriodSelector(selected: String, onSelect: (String) -> Unit) { val periods = listOf("1D", "1W", "1M", "3M", "6M", "1Y", "5Y"); Row(Modifier.horizontalScroll(rememberScrollState()), horizontalArrangement = Arrangement.spacedBy(7.dp)) { periods.forEach { period -> Surface(modifier = Modifier.width(57.dp).height(34.dp).clickable { onSelect(period) }, shape = RoundedCornerShape(10.dp), color = if (period == selected) AGreen else Color.Transparent, border = if (period == selected) null else BorderStroke(1.dp, Color(0xFF7D7D7D))) { Box(Modifier.fillMaxSize(), Alignment.Center) { Text(period, color = if (period == selected) Color.White else AText, fontSize = 10.sp, fontWeight = FontWeight.Bold) } } } } }
@Composable private fun MarketLineChart(values: List<Float>) { Canvas(Modifier.fillMaxWidth().height(180.dp).padding(horizontal = 4.dp)) { if (values.size < 2) return@Canvas; repeat(4) { i -> val y = size.height * i / 3f; drawLine(Color(0xFFE8EFEB), Offset(0f, y), Offset(size.width, y), strokeWidth = 1f) }; val min = values.minOrNull() ?: 0f; val max = values.maxOrNull() ?: 1f; val range = (max - min).takeIf { it > 0f } ?: 1f; val path = Path(); values.forEachIndexed { index, value -> val x = index * size.width / (values.lastIndex.coerceAtLeast(1)); val y = size.height - ((value - min) / range) * (size.height - 16.dp.toPx()) - 8.dp.toPx(); if (index == 0) path.moveTo(x, y) else path.lineTo(x, y) }; drawPath(path, AGreen, style = Stroke(width = 3.dp.toPx(), cap = StrokeCap.Round)); val last = values.lastIndex; val lx = last * size.width / (values.lastIndex.coerceAtLeast(1)); val ly = size.height - ((values.last() - min) / range) * (size.height - 16.dp.toPx()) - 8.dp.toPx(); drawCircle(AGreen, 5.dp.toPx(), Offset(lx, ly)) } }
private fun marketTrend(period: String): List<Float> { val base = listOf(1710f, 1725f, 1718f, 1740f, 1734f, 1752f, 1768f, 1775f, 1758f, 1770f, 1784f, 1790f, 1802f, 1794f, 1812f, 1807f, 1820f, 1814f, 1828f, 1843f); return when (period) { "1D" -> base.takeLast(8); "1W" -> base.takeLast(10); "1M" -> base; "3M" -> base.mapIndexed { i, v -> v - 90f + i * 4.7f }; "6M" -> base.mapIndexed { i, v -> v - 150f + i * 7.5f }; "1Y" -> base.mapIndexed { i, v -> v - 260f + i * 13.5f }; else -> base.mapIndexed { i, v -> v - 500f + i * 31f } } }
@Composable private fun BreadthCard(advancers: Int, decliners: Int) { Card(Modifier.fillMaxWidth(), RoundedCornerShape(16.dp), border = BorderStroke(1.dp, ABorder)) { Column(Modifier.padding(15.dp)) { Row(verticalAlignment = Alignment.CenterVertically) { Icon(Icons.Default.BarChart, null, tint = AGreen); Spacer(Modifier.width(8.dp)); Column { Text("Market Breadth", fontWeight = FontWeight.ExtraBold, fontSize = 15.sp); Text("Advancers vs Decliners", color = AMuted, fontSize = 10.sp) } }; Spacer(Modifier.height(13.dp)); Row(Modifier.fillMaxWidth().height(9.dp).clip(RoundedCornerShape(10.dp))) { Box(Modifier.weight(advancers.coerceAtLeast(1).toFloat()).fillMaxHeight().background(AGreen)); Box(Modifier.weight(decliners.coerceAtLeast(1).toFloat()).fillMaxHeight().background(ARed)) }; Spacer(Modifier.height(10.dp)); Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) { Text("●  $advancers Advancers", color = AGreen, fontSize = 10.sp, fontWeight = FontWeight.Bold); Text("●  $decliners Decliners", color = ARed, fontSize = 10.sp, fontWeight = FontWeight.Bold) } } } }
@Composable private fun SectorCard() { val sectors = listOf("Banking" to 2.48, "Telecom" to 1.87, "Manufacturing" to 0.67, "Energy" to -1.21, "Retail" to 0.34); Card(Modifier.fillMaxWidth(), RoundedCornerShape(16.dp), border = BorderStroke(1.dp, ABorder)) { Column(Modifier.padding(15.dp)) { Row(verticalAlignment = Alignment.CenterVertically) { Icon(Icons.Default.PieChart, null, tint = AGreen); Spacer(Modifier.width(8.dp)); Column { Text("Sector Performance", fontWeight = FontWeight.ExtraBold, fontSize = 15.sp); Text("Top sectors by daily change", color = AMuted, fontSize = 10.sp) } }; Spacer(Modifier.height(11.dp)); sectors.forEach { (name, change) -> Row(Modifier.fillMaxWidth().padding(vertical = 4.dp), verticalAlignment = Alignment.CenterVertically) { Text(name, Modifier.width(92.dp), fontSize = 10.sp); Box(Modifier.weight(1f).height(7.dp).clip(RoundedCornerShape(8.dp)).background(Color(0xFFEAF1ED))) { Box(Modifier.fillMaxHeight().fillMaxWidth((kotlin.math.abs(change) / 2.5).coerceIn(0.05, 1.0).toFloat()).background(if (change >= 0) AGreen else ARed)) }; Text(String.format("%+.2f%%", change), Modifier.width(55.dp), color = if (change >= 0) AGreen else ARed, fontSize = 10.sp, fontWeight = FontWeight.Bold) } } } } }
@Composable private fun MoversCard(gainers: List<Stock>, losers: List<Stock>) { Card(Modifier.fillMaxWidth(), RoundedCornerShape(16.dp), border = BorderStroke(1.dp, ABorder)) { Column(Modifier.padding(15.dp)) { Row(verticalAlignment = Alignment.CenterVertically) { Icon(Icons.Default.SwapVert, null, tint = AGreen); Spacer(Modifier.width(8.dp)); Text("Top Movers", fontWeight = FontWeight.ExtraBold, fontSize = 15.sp) }; Spacer(Modifier.height(10.dp)); Row(horizontalArrangement = Arrangement.spacedBy(16.dp)) { Column(Modifier.weight(1f)) { Text("↑ Top Gainers", color = AGreen, fontWeight = FontWeight.Bold, fontSize = 10.sp); gainers.take(5).forEach { MoverRow(it, true) } }; Column(Modifier.weight(1f)) { Text("↓ Top Losers", color = ARed, fontWeight = FontWeight.Bold, fontSize = 10.sp); losers.take(5).forEach { MoverRow(it, false) } } } } } }
