@Composable private fun ApprovedCompany(stock: Stock?, onBack: () -> Unit) { var period by rememberSaveable { mutableStateOf("1Y") }; var history by remember(stock?.symbol) { mutableStateOf(stock?.history ?: emptyList()) }; LaunchedEffect(stock?.symbol, period) { stock?.symbol?.let { loaded -> MyStocksCache.loadHistory(loaded, period).takeIf { it.size >= 2 }?.let { history = it } } }; LazyColumn(contentPadding = PaddingValues(20.dp), verticalArrangement = Arrangement.spacedBy(12.dp)) { item { Row(verticalAlignment = Alignment.CenterVertically) { IconButton(onClick = onBack) { Icon(Icons.Default.ArrowBack, "Back") }; Column { Text(stock?.name ?: "Company", fontSize = 20.sp, fontWeight = FontWeight.ExtraBold); Text("${stock?.symbol ?: "—"} • NSE", color = AMuted, fontSize = 10.sp) } } }; item { Text("NSE DATA • 15 MIN DELAYED", color = AGreen, fontWeight = FontWeight.Bold, fontSize = 10.sp) }; item { Card(Modifier.fillMaxWidth(), RoundedCornerShape(18.dp), border = BorderStroke(1.dp, ABorder)) { Column(Modifier.padding(15.dp)) { Text("Price History", fontWeight = FontWeight.ExtraBold, fontSize = 16.sp); Spacer(Modifier.height(8.dp)); MarketLineChart(history.map { it.toFloat() }); PeriodSelector(period) { period = it } } } }; item { Card(Modifier.fillMaxWidth(), RoundedCornerShape(16.dp), colors = CardDefaults.cardColors(containerColor = ALightGreen)) { Column(Modifier.padding(15.dp)) { Text("NSE Watcher Score", fontWeight = FontWeight.ExtraBold); Text("Analysis factors will combine price, fundamentals, news, events and market conditions.", color = AMuted, fontSize = 11.sp) } } } } }
@Composable private fun ApprovedProfile(onBack: () -> Unit, onSettings: () -> Unit) { LazyColumn(contentPadding = PaddingValues(20.dp), verticalArrangement = Arrangement.spacedBy(12.dp)) { item { Row(verticalAlignment = Alignment.CenterVertically) { IconButton(onClick = onBack) { Icon(Icons.Default.ArrowBack, "Back") }; Text("Profile", fontSize = 22.sp, fontWeight = FontWeight.ExtraBold) } }; item { Card(Modifier.fillMaxWidth(), RoundedCornerShape(20.dp), colors = CardDefaults.cardColors(containerColor = ALightGreen)) { Column(Modifier.fillMaxWidth().padding(20.dp), horizontalAlignment = Alignment.CenterHorizontally) { Surface(modifier = Modifier.size(70.dp), shape = CircleShape, color = Color.White) { Box(Modifier.fillMaxSize(), Alignment.Center) { Text("J", fontSize = 28.sp, color = AGreen, fontWeight = FontWeight.Bold) } }; Spacer(Modifier.height(10.dp)); Text("James Waweru", fontSize = 18.sp, fontWeight = FontWeight.ExtraBold); Text("IT Graduate | Investor | Learner", color = AMuted, fontSize = 11.sp) } } }; item { Card(Modifier.fillMaxWidth().clickable(onClick = onSettings), RoundedCornerShape(16.dp), border = BorderStroke(1.dp, ABorder)) { Row(Modifier.padding(15.dp), verticalAlignment = Alignment.CenterVertically) { Icon(Icons.Default.Settings, null, tint = AGreen); Spacer(Modifier.width(12.dp)); Column(Modifier.weight(1f)) { Text("Settings", fontWeight = FontWeight.Bold); Text("App, alerts, charts, privacy and display", color = AMuted, fontSize = 10.sp) }; Icon(Icons.Default.ChevronRight, null, tint = AMuted) } } } } }
@Composable private fun ApprovedSettings(dark: Boolean, onDarkChange: (Boolean) -> Unit, onBack: () -> Unit) { LazyColumn(contentPadding = PaddingValues(20.dp), verticalArrangement = Arrangement.spacedBy(10.dp)) { item { Row(verticalAlignment = Alignment.CenterVertically) { IconButton(onClick = onBack) { Icon(Icons.Default.ArrowBack, "Back") }; Text("Settings", fontSize = 22.sp, fontWeight = FontWeight.ExtraBold) } }; item { SettingRow(Icons.Default.DarkMode, "Dark mode", "Appearance", dark) { onDarkChange(it) } }; item { SettingRow(Icons.Default.Notifications, "Notifications", "Market, price and news alerts", null) {} }; item { SettingRow(Icons.Default.ShowChart, "Chart settings", "Timeframes and chart display", null) {} }; item { SettingRow(Icons.Default.Security, "Privacy & security", "Your account and data", null) } } }
@Composable private fun SettingRow(icon: androidx.compose.ui.graphics.vector.ImageVector, title: String, subtitle: String, checked: Boolean?, onChecked: (Boolean) -> Unit) { Card(Modifier.fillMaxWidth(), RoundedCornerShape(15.dp), border = BorderStroke(1.dp, ABorder)) { Row(Modifier.padding(14.dp), verticalAlignment = Alignment.CenterVertically) { Icon(icon, null, tint = AGreen); Spacer(Modifier.width(12.dp)); Column(Modifier.weight(1f)) { Text(title, fontWeight = FontWeight.Bold); Text(subtitle, color = AMuted, fontSize = 10.sp) }; if (checked != null) Switch(checked, onCheckedChange = onChecked) else Icon(Icons.Default.ChevronRight, null, tint = AMuted) } } }
@Composable private fun ApprovedSimplePage(title: String, icon: androidx.compose.ui.graphics.vector.ImageVector, message: String) { Column(Modifier.fillMaxSize().padding(24.dp), verticalArrangement = Arrangement.Center, horizontalAlignment = Alignment.CenterHorizontally) { Surface(modifier = Modifier.size(64.dp), shape = CircleShape, color = ALightGreen) { Icon(icon, null, Modifier.padding(16.dp), AGreen) }; Spacer(Modifier.height(14.dp)); Text(title, fontSize = 22.sp, fontWeight = FontWeight.ExtraBold); Text(message, color = AMuted, fontSize = 12.sp, modifier = Modifier.padding(top = 5.dp)) } }
